      },
      "tagColor": {
        "dataType": "color",
        "displayName": "Tag Background",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "tagTextColor": {
        "dataType": "color",
        "displayName": "Tag Text Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
