function Component({ config = {} }) {
  const placeholder = config?.placeholder || 'Add tags...';
  const defaultTags = (config?.defaultTags || 'React,JavaScript,TypeScript,CSS')
    .split(',')
    .map(t => t.trim())
    .filter(t => t);
  const maxTags = config?.maxTags === 'unlimited' ? Infinity : parseInt(config?.maxTags || '10');
  const allowDuplicates = config?.allowDuplicates === true;
  const showCount = config?.showCount !== false;
  const inputWidth = config?.inputWidth || '500';
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const tagColor = config?.tagColor || '#495057';
  const tagTextColor = config?.tagTextColor || '#FFFFFF';
  const accentColor = config?.accentColor || '#495057';

  const [tags, setTags] = React.useState(defaultTags);
  const [inputValue, setInputValue] = React.useState('');
  const [focusedTagIndex, setFocusedTagIndex] = React.useState(null);
  const [removingTag, setRemovingTag] = React.useState(null);

  const inputRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const addTag = (tag) => {
    const trimmed = tag.trim();
    if (!trimmed) return;

    if (!allowDuplicates && tags.includes(trimmed)) {
      return;
    }

    if (tags.length >= maxTags) {
      return;
    }

    setTags([...tags, trimmed]);
    setInputValue('');
  };

  const removeTag = (index) => {
    if (!prefersReducedMotion) {
      setRemovingTag(index);
      setTimeout(() => {
        setTags(tags.filter((_, i) => i !== index));
        setRemovingTag(null);
      }, 300);
    } else {
      setTags(tags.filter((_, i) => i !== index));
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addTag(inputValue);
    } else if (e.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      removeTag(tags.length - 1);
    } else if (e.key === 'ArrowLeft' && inputValue === '' && tags.length > 0) {
      setFocusedTagIndex(tags.length - 1);
    }
  };

  const handleTagKeyDown = (e, index) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      removeTag(index);
      setFocusedTagIndex(null);
      inputRef.current?.focus();
    } else if (e.key === 'ArrowLeft' && index > 0) {
      setFocusedTagIndex(index - 1);
    } else if (e.key === 'ArrowRight') {
      if (index < tags.length - 1) {
        setFocusedTagIndex(index + 1);
      } else {
        setFocusedTagIndex(null);
        inputRef.current?.focus();
      }
    }
  };

  React.useEffect(() => {
    if (focusedTagIndex !== null) {
      document.getElementById(`tag-${focusedTagIndex}`)?.focus();
    }
  }, [focusedTagIndex]);

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{
        width: inputWidth === '100%' ? '100%' : `${inputWidth}px`,
        maxWidth: '100%'
      }}>
        <div style={{
          padding: '16px',
          backgroundColor: `${accentColor}08`,
          border: `2px solid ${accentColor}20`,
          borderRadius: '8px',
          minHeight: '120px',
          display: 'flex',
          flexWrap: 'wrap',
          gap: '8px',
          alignItems: 'flex-start',
          transition: 'border-color 200ms ease-out'
        }}>
          {tags.map((tag, index) => (
            <div
              key={index}
              id={`tag-${index}`}
              tabIndex={0}
              onKeyDown={(e) => handleTagKeyDown(e, index)}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '8px',
                padding: '6px 12px',
                backgroundColor: tagColor,
                color: tagTextColor,
                fontSize: '14px',
                fontWeight: '400',
                borderRadius: '6px',
                letterSpacing: '0.025em',
                opacity: prefersReducedMotion ? 1 : (removingTag === index ? 0 : 1),
                transform: prefersReducedMotion ? 'none' : (removingTag === index ? 'scale(0.8)' : 'scale(1)'),
                transition: 'all 300ms ease-out',
                outline: focusedTagIndex === index ? `2px solid ${accentColor}` : 'none',
                outlineOffset: '2px'
              }}
            >
              <span>{tag}</span>
              <button
                onClick={() => removeTag(index)}
                aria-label={`Remove ${tag}`}
                style={{
                  background: 'none',
                  border: 'none',
                  color: tagTextColor,
                  cursor: 'pointer',
                  padding: '0',
                  width: '16px',
                  height: '16px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '16px',
                  opacity: 0.7,
                  transition: 'opacity 200ms ease-out'
                }}
                onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
                onMouseLeave={(e) => e.currentTarget.style.opacity = '0.7'}
              >
                ×
              </button>
            </div>
          ))}

          <input
            ref={inputRef}
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={tags.length === 0 ? placeholder : ''}
            disabled={tags.length >= maxTags}
            style={{
              flex: 1,
              minWidth: '120px',
              border: 'none',
              outline: 'none',
              backgroundColor: 'transparent',
              fontSize: '14px',
              color: textColor,
              padding: '6px 0',
              fontFamily: 'inherit'
            }}
          />
        </div>

        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginTop: '12px',
          fontSize: '13px',
          color: accentColor
        }}>
          {showCount && (
            <span>
              {tags.length} {tags.length === 1 ? 'tag' : 'tags'}
              {maxTags !== Infinity && ` (max ${maxTags})`}
            </span>
          )}
          <span style={{ fontSize: '12px', fontStyle: 'italic' }}>
            Press Enter or comma to add
          </span>
        </div>

        {tags.length > 0 && (
          <div style={{
            marginTop: '24px',
            padding: '16px',
            backgroundColor: `${accentColor}08`,
            borderRadius: '8px',
            border: `1px solid ${accentColor}20`
          }}>
            <div style={{
              fontSize: '12px',
              fontWeight: '500',
              color: accentColor,
              marginBottom: '8px',
              letterSpacing: '0.05em',
              textTransform: 'uppercase'
            }}>
              Output
            </div>
            <div style={{
              fontSize: '14px',
              color: textColor,
              fontFamily: '"SF Mono", Monaco, monospace',
              wordBreak: 'break-all'
            }}>
              {JSON.stringify(tags)}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

interactive-fileuploaddropzone:
const MANIFEST = {
  "type": "Interactive.FileUploadDropzone",
  "description": "File upload dropzone with drag-over highlight, progress indicators, and file previews",
  "editorElement": {
    "selector": ".file-upload-dropzone",
    "displayName": "File Upload Dropzone",
    "archetype": "container",
    "data": {
      "allowMultiple": {
        "dataType": "booleanValue",
        "displayName": "Allow Multiple Files",
        "defaultValue": true,
        "group": "Content"
      },
      "maxFiles": {
        "dataType": "select",
        "displayName": "Max Files",
        "defaultValue": "5",
        "options": ["1", "3", "5", "10", "unlimited"],
        "group": "Content"
      },
      "acceptedTypes": {
        "dataType": "text",
        "displayName": "Accepted File Types",
        "defaultValue": "image/*,.pdf,.doc,.docx",
        "group": "Content"
      },
      "maxSizeMB": {
        "dataType": "select",
        "displayName": "Max File Size (MB)",
        "defaultValue": "10",
        "options": ["1", "5", "10", "25", "50"],
        "group": "Content"
      },
      "showPreviews": {
        "dataType": "booleanValue",
        "displayName": "Show File Previews",
        "defaultValue": true,
        "group": "Content"
      },
      "dropzoneHeight": {
        "dataType": "select",
        "displayName": "Dropzone Height",
        "defaultValue": "200",
        "options": ["150", "200", "250", "300"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      },
      "dragOverColor": {
        "dataType": "color",
        "displayName": "Drag Over Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "progressColor": {
        "dataType": "color",
        "displayName": "Progress Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const allowMultiple = config?.allowMultiple !== false;
  const maxFiles = config?.maxFiles === 'unlimited' ? Infinity : parseInt(config?.maxFiles || '5');
  const acceptedTypes = config?.acceptedTypes || 'image/*,.pdf,.doc,.docx';
  const maxSizeMB = parseInt(config?.maxSizeMB || '10');
  const showPreviews = config?.showPreviews !== false;
  const dropzoneHeight = parseInt(config?.dropzoneHeight || '200');
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const borderColor = config?.borderColor || '#E4E4E7';
  const dragOverColor = config?.dragOverColor || '#495057';
  const accentColor = config?.accentColor || '#495057';
  const progressColor = config?.progressColor || '#495057';

  const [files, setFiles] = React.useState([]);
  const [isDragOver, setIsDragOver] = React.useState(false);
  const [uploadProgress, setUploadProgress] = React.useState({});

  const fileInputRef = React.useRef(null);
  const dragCounterRef = React.useRef(0);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
  };

  const validateFile = (file) => {
    if (file.size > maxSizeMB * 1024 * 1024) {
      return { valid: false, error: `File exceeds ${maxSizeMB}MB limit` };
    }
    return { valid: true };
  };

  const simulateUpload = (fileId) => {
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
      }
      setUploadProgress(prev => ({ ...prev, [fileId]: progress }));
    }, 200);
  };

  const handleFiles = (fileList) => {
    const newFiles = Array.from(fileList);

    if (!allowMultiple && newFiles.length > 1) {
      alert('Only one file allowed');
      return;
    }

    if (files.length + newFiles.length > maxFiles) {
      alert(`Maximum ${maxFiles} files allowed`);
      return;
    }

    const validFiles = newFiles
      .map(file => {
        const validation = validateFile(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          file,
          name: file.name,
          size: file.size,
          type: file.type,
          preview: file.type.startsWith('image/') ? URL.createObjectURL(file) : null,
          error: validation.valid ? null : validation.error
        };
      })
      .filter(f => !f.error);

    validFiles.forEach(f => {
      if (!f.error) {
        simulateUpload(f.id);
      }
    });

    setFiles(prev => [...prev, ...validFiles]);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);
    dragCounterRef.current = 0;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const handleDragEnter = (e) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current++;
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      setIsDragOver(true);
    }
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current--;
    if (dragCounterRef.current === 0) {
      setIsDragOver(false);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const removeFile = (id) => {
    setFiles(files.filter(f => f.id !== id));
    setUploadProgress(prev => {
      const newProgress = { ...prev };
      delete newProgress[id];
      return newProgress;
    });
  };

  const getFileIcon = (type) => {
    if (type.startsWith('image/')) return '🖼️';
    if (type.includes('pdf')) return '📄';
    if (type.includes('word') || type.includes('doc')) return '📝';
    if (type.includes('sheet') || type.includes('excel')) return '📊';
    if (type.includes('video')) return '🎥';
    if (type.includes('audio')) return '🎵';
    return '📎';
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{ width: '100%', maxWidth: '600px' }}>
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragEnter={handleDragEnter}
          onDragLeave={handleDragLeave}
          onClick={() => fileInputRef.current?.click()}
          style={{
            height: `${dropzoneHeight}px`,
            border: `2px dashed ${isDragOver ? dragOverColor : borderColor}`,
            borderRadius: '12px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            backgroundColor: isDragOver ? `${dragOverColor}10` : `${accentColor}05`,
            transition: 'all 300ms ease-out',
            transform: prefersReducedMotion ? 'none' : (isDragOver ? 'scale(1.02)' : 'scale(1)'),
            padding: '20px'
          }}
        >
          <div style={{
            fontSize: '48px',
            marginBottom: '16px',
            opacity: isDragOver ? 1 : 0.5,
            transition: 'opacity 200ms ease-out'
          }}>
            📁
          </div>
          <div style={{
            fontSize: '16px',
            fontWeight: '500',
            color: textColor,
            marginBottom: '8px',
            textAlign: 'center'
          }}>
            {isDragOver ? 'Drop files here' : 'Drag & drop files here'}
          </div>
          <div style={{
            fontSize: '14px',
            color: accentColor,
            marginBottom: '16px',
            textAlign: 'center'
          }}>
            or click to browse
          </div>
          <div style={{
            fontSize: '13px',
            color: accentColor,
            textAlign: 'center',
            opacity: 0.7
          }}>
            Max {maxFiles === Infinity ? 'unlimited' : maxFiles} files • {maxSizeMB}MB each
          </div>
        </div>

        <input
          ref={fileInputRef}
          type="file"
          multiple={allowMultiple}
          accept={acceptedTypes}
          onChange={(e) => handleFiles(e.target.files)}
          style={{ display: 'none' }}
        />

        {files.length > 0 && (
          <div style={{
            marginTop: '24px',
            display: 'flex',
            flexDirection: 'column',
            gap: '12px'
          }}>
            {files.map((file, index) => {
              const progress = uploadProgress[file.id] || 0;
              const isComplete = progress === 100;

              return (
                <div
                  key={file.id}
                  style={{
                    padding: '16px',
                    backgroundColor: `${accentColor}08`,
                    borderRadius: '8px',
                    border: `1px solid ${accentColor}20`,
                    opacity: prefersReducedMotion ? 1 : 1,
                    transform: prefersReducedMotion ? 'none' : 'translateY(0)',
                    animation: prefersReducedMotion ? 'none' : `slideIn 400ms ease-out ${index * 80}ms backwards`
                  }}
                >
                  <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
                    {showPreviews && file.preview ? (
                      <img
                        src={file.preview}
                        alt={file.name}
                        style={{
                          width: '60px',
                          height: '60px',
                          objectFit: 'cover',
                          borderRadius: '6px',
                          flexShrink: 0
                        }}
                      />
                    ) : (
                      <div style={{
                        width: '60px',
                        height: '60px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '32px',
                        backgroundColor: `${accentColor}15`,
                        borderRadius: '6px',
                        flexShrink: 0
                      }}>
                        {getFileIcon(file.type)}
                      </div>
                    )}

                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{
                        fontSize: '14px',
                        fontWeight: '500',
                        color: textColor,
                        marginBottom: '4px',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'
                      }}>
                        {file.name}
                      </div>
                      <div style={{
                        fontSize: '13px',
                        color: accentColor,
                        marginBottom: '8px'
                      }}>
                        {formatFileSize(file.size)}
                      </div>

                      <div style={{
                        height: '6px',
                        backgroundColor: `${accentColor}20`,
                        borderRadius: '3px',
                        overflow: 'hidden'
                      }}>
                        <div style={{
                          height: '100%',
                          width: `${progress}%`,
                          backgroundColor: isComplete ? '#10B981' : progressColor,
                          transition: 'width 200ms ease-out, background-color 200ms ease-out',
                          borderRadius: '3px'
                        }} />
                      </div>

                      <div style={{
                        fontSize: '12px',
                        color: accentColor,
                        marginTop: '6px'
                      }}>
                        {isComplete ? '✓ Upload complete' : `Uploading... ${Math.round(progress)}%`}
                      </div>
                    </div>

                    <button
                      onClick={() => removeFile(file.id)}
                      aria-label="Remove file"
                      style={{
                        background: 'none',
                        border: 'none',
                        color: accentColor,
                        cursor: 'pointer',
                        fontSize: '20px',
                        padding: '4px',
                        opacity: 0.7,
                        transition: 'opacity 200ms ease-out',
                        flexShrink: 0
                      }}
                      onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
                      onMouseLeave={(e) => e.currentTarget.style.opacity = '0.7'}
                    >
                      ×
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        <style jsx>{`
          @keyframes slideIn {
            from {
              opacity: 0;
              transform: translateY(20px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }

          @media (prefers-reduced-motion: reduce) {
            * {
              animation-duration: 0.01ms !important;
              animation-iteration-count: 1 !important;
              transition-duration: 0.01ms !important;
            }
          }
        `}</style>
      </div>
    </div>
  );
}

