  );

  return (
    <div 
      className="form-wizard-container"
      style={{
        backgroundColor,
        padding: '48px 24px',
        fontFamily,
        minHeight: '700px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center'
      }}
    >
      <div style={{
        backgroundColor: cardBackgroundColor,
        border: `1px solid ${borderColor}`,
        borderRadius: '12px',
        padding: '40px',
        maxWidth: '600px',
        width: '100%'
      }}>
        {/* Progress Bar */}
        <div style={{
          marginBottom: '32px'
        }}>
          <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            marginBottom: '12px'
          }}>
            {steps.map((step, index) => (
              <div
                key={index}
                style={{
                  flex: 1,
                  textAlign: 'center',
                  fontSize: '12px',
                  fontWeight: '500',
                  color: index <= currentStep ? progressColor : descriptionColor,
                  transition: prefersReducedMotion ? 'none' : 'color 300ms ease-out'
                }}
              >
                {index + 1}
              </div>
            ))}
          </div>

          <div style={{
            height: '4px',
            backgroundColor: progressBackgroundColor,
            borderRadius: '2px',
            overflow: 'hidden'
          }}>
            <div style={{
              height: '100%',
              backgroundColor: progressColor,
              width: `${((currentStep + 1) / steps.length) * 100}%`,
              transition: prefersReducedMotion ? 'none' : 'width 400ms cubic-bezier(0.22, 1, 0.36, 1)'
            }} />
          </div>
        </div>

        {/* Step Content */}
        <div style={{
          minHeight: '400px',
          position: 'relative',
          overflow: 'hidden'
        }}>
          <div
            key={currentStep}
            style={{
              opacity: 0,
              transform: prefersReducedMotion ? 'none' : (
                direction === 'forward' ? 'translateX(40px)' : 'translateX(-40px)'
              ),
              animation: prefersReducedMotion ? 'none' : 'stepAppear 400ms ease-out forwards'
            }}
          >
            <h2 style={{
              margin: '0 0 8px 0',
              fontSize: `${titleSize}px`,
              fontWeight: '500',
              color: titleColor
            }}>
              {steps[currentStep].title}
            </h2>

            <p style={{
              margin: '0 0 32px 0',
              fontSize: '14px',
              color: descriptionColor
            }}>
              {steps[currentStep].description}
            </p>

            {/* Step 1: Personal Information */}
            {currentStep === 0 && (
              <>
                {renderInput('name', 'Full Name')}
                {renderInput('email', 'Email Address', 'email')}
                {renderInput('company', 'Company Name')}
              </>
            )}

            {/* Step 2: Project Details */}
            {currentStep === 1 && (
              <>
                {renderSelect('projectType', 'Project Type', ['Web Design', 'Mobile App', 'Branding', 'Consulting'])}
                {renderTextarea('description', 'Project Description')}
              </>
            )}

            {/* Step 3: Timeline & Budget */}
            {currentStep === 2 && (
              <>
                {renderSelect('timeline', 'Project Timeline', ['1-2 months', '3-4 months', '5-6 months', '6+ months'])}
                {renderSelect('budget', 'Budget Range', ['< $10k', '$10k - $25k', '$25k - $50k', '$50k+'])}
              </>
            )}

            {/* Step 4: Review */}
            {currentStep === 3 && (
              <div style={{
                backgroundColor: '#F8F9FA',
                padding: '24px',
                borderRadius: '8px'
              }}>
                <h3 style={{ margin: '0 0 16px 0', fontSize: '16px', fontWeight: '500', color: titleColor }}>
                  Review Your Information
                </h3>
                {Object.entries(formData).map(([key, value]) => (
                  value && (
                    <div key={key} style={{ marginBottom: '12px' }}>
                      <div style={{ fontSize: '12px', color: labelColor, textTransform: 'capitalize' }}>
                        {key.replace(/([A-Z])/g, ' $1').trim()}
                      </div>
                      <div style={{ fontSize: '14px', color: titleColor, fontWeight: '500' }}>
                        {value}
                      </div>
                    </div>
                  )
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Navigation Buttons */}
        <div style={{
          display: 'flex',
          gap: '12px',
          marginTop: '32px'
        }}>
          {currentStep > 0 && (
            <button
              onClick={handlePrev}
              style={{
                flex: 1,
                padding: '14px',
                backgroundColor: 'transparent',
                color: buttonColor,
                border: `1px solid ${borderColor}`,
                borderRadius: '6px',
                fontSize: '15px',
                fontWeight: '500',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
                fontFamily
              }}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) {
                  e.currentTarget.style.borderColor = buttonColor;
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = borderColor;
              }}
            >
              Previous
            </button>
          )}

          <button
            onClick={currentStep === steps.length - 1 ? handleSubmit : handleNext}
            style={{
              flex: 1,
              padding: '14px',
              backgroundColor: buttonColor,
              color: buttonTextColor,
              border: 'none',
              borderRadius: '6px',
              fontSize: '15px',
              fontWeight: '500',
              cursor: 'pointer',
              transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
              fontFamily
            }}
            onMouseEnter={(e) => {
              if (!prefersReducedMotion) {
                e.currentTarget.style.backgroundColor = buttonHoverColor;
              }
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = buttonColor;
            }}
          >
            {currentStep === steps.length - 1 ? submitButtonText : 'Next'}
          </button>
        </div>
      </div>

      <style>{`
        @keyframes stepAppear {
          from {
            opacity: 0;
            transform: translateX(${direction === 'forward' ? '40px' : '-40px'});
          }
          to {
            opacity: 1;
            transform: translateX(0);
          }
        }
      `}</style>
    </div>
  );
}

