// Component #10: Multi-Step Form Wizard
const MANIFEST = {
  "type": "Forms.MultiStepWizard",
  "description": "Sophisticated multi-step form with validation, conditional logic, and smooth transitions",
  "editorElement": {
    "selector": ".form-wizard",
    "displayName": "Multi-Step Form Wizard",
    "archetype": "container",
    "data": {
      "step1Title": { "dataType": "text", "displayName": "Step 1 Title", "defaultValue": "Personal Information", "group": "Content" },
      "step2Title": { "dataType": "text", "displayName": "Step 2 Title", "defaultValue": "Business Details", "group": "Content" },
      "step3Title": { "dataType": "text", "displayName": "Step 3 Title", "defaultValue": "Preferences", "group": "Content" },
      "step4Title": { "dataType": "text", "displayName": "Step 4 Title", "defaultValue": "Review & Submit", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background", "defaultValue": "#FFFFFF", "group": "Colors" },
      "primaryColor": { "dataType": "color", "displayName": "Primary Color", "defaultValue": "#495057", "group": "Colors" },
      "errorColor": { "dataType": "color", "displayName": "Error Color", "defaultValue": "#DC2626", "group": "Colors" },
      "successColor": { "dataType": "color", "displayName": "Success Color", "defaultValue": "#2D7D3E", "group": "Colors" },
      "borderColor": { "dataType": "color", "displayName": "Border Color", "defaultValue": "#E9ECEF", "group": "Colors" },
      "inputBg": { "dataType": "color", "displayName": "Input Background", "defaultValue": "#F8F9FA", "group": "Colors" },
      "textColor": { "dataType": "color", "displayName": "Text Color", "defaultValue": "#212529", "group": "Colors" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config }) {
  const [currentStep, setCurrentStep] = useState(1);
  const [direction, setDirection] = useState('forward');
  const [formData, setFormData] = useState({
    firstName: '', lastName: '', email: '', phone: '',
    company: '', industry: '', employees: '',
    newsletter: false, notifications: true,
    businessType: ''
  });
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  const totalSteps = 4;

  const validate = (field, value) => {
    switch (field) {
      case 'email':
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value) ? '' : 'Invalid email';
      case 'phone':
        return /^\d{10}$/.test(value.replace(/\D/g, '')) ? '' : 'Invalid phone (10 digits)';
      case 'firstName':
      case 'lastName':
      case 'company':
        return value.trim().length > 0 ? '' : 'This field is required';
      default:
        return '';
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (touched[field]) {
      const error = validate(field, value);
      setErrors(prev => ({ ...prev, [field]: error }));
    }
  };

  const handleBlur = (field) => {
    setTouched(prev => ({ ...prev, [field]: true }));
    const error = validate(field, formData[field]);
    setErrors(prev => ({ ...prev, [field]: error }));
  };

  const canProceed = (step) => {
    switch (step) {
      case 1:
        return !validate('firstName', formData.firstName) && 
               !validate('lastName', formData.lastName) && 
               !validate('email', formData.email);
      case 2:
        return !validate('company', formData.company) && formData.industry;
      case 3:
        return true;
      default:
        return true;
    }
  };

  const nextStep = () => {
    if (canProceed(currentStep) && currentStep < totalSteps) {
      setDirection('forward');
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      setDirection('backward');
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = () => {
    setIsSubmitted(true);
  };

  const renderStepContent = () => {
    const slideClass = direction === 'forward' ? 'slide-in-right' : 'slide-in-left';

    if (isSubmitted) {
      return (
        <div key="success" className={slideClass} style={{
          textAlign: 'center',
          padding: '60px 40px',
          animation: 'fadeInScale 500ms ease-out'
        }}>
          <div style={{
            width: '80px',
            height: '80px',
            borderRadius: '50%',
            backgroundColor: config?.successColor || '#2D7D3E',
            margin: '0 auto 24px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            animation: 'successPop 600ms ease-out'
          }}>
            <svg width="40" height="40" viewBox="0 0 24 24" fill="none">
              <path d="M20 6L9 17L4 12" stroke="#FFFFFF" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
          <h2 style={{ fontSize: '28px', fontWeight: '500', color: config?.textColor || '#212529', marginBottom: '12px' }}>
            Submission Successful!
          </h2>
          <p style={{ fontSize: '16px', color: '#6C757D' }}>
            Thank you for completing the form. We'll be in touch soon.
          </p>
        </div>
      );
    }

    switch (currentStep) {
      case 1:
        return (
          <div key="step1" className={slideClass}>
            <h2 style={{ fontSize: '24px', fontWeight: '500', marginBottom: '24px', color: config?.textColor || '#212529' }}>
              {config?.step1Title || 'Personal Information'}
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                    First Name *
                  </label>
                  <input
                    type="text"
                    value={formData.firstName}
                    onChange={(e) => handleChange('firstName', e.target.value)}
                    onBlur={() => handleBlur('firstName')}
                    style={{
                      width: '100%',
                      padding: '12px',
                      fontSize: '15px',
                      border: `1px solid ${errors.firstName && touched.firstName ? (config?.errorColor || '#DC2626') : (config?.borderColor || '#E9ECEF')}`,
                      borderRadius: '6px',
                      backgroundColor: config?.inputBg || '#F8F9FA',
                      fontFamily: 'inherit',
                      transition: 'border-color 200ms ease-out'
                    }}
                  />
                  {errors.firstName && touched.firstName && (
                    <div style={{ fontSize: '13px', color: config?.errorColor || '#DC2626', marginTop: '4px', animation: 'shake 300ms' }}>
                      {errors.firstName}
                    </div>
                  )}
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                    Last Name *
                  </label>
                  <input
                    type="text"
                    value={formData.lastName}
                    onChange={(e) => handleChange('lastName', e.target.value)}
                    onBlur={() => handleBlur('lastName')}
                    style={{
                      width: '100%',
                      padding: '12px',
                      fontSize: '15px',
                      border: `1px solid ${errors.lastName && touched.lastName ? (config?.errorColor || '#DC2626') : (config?.borderColor || '#E9ECEF')}`,
                      borderRadius: '6px',
                      backgroundColor: config?.inputBg || '#F8F9FA',
                      fontFamily: 'inherit'
                    }}
                  />
                  {errors.lastName && touched.lastName && (
                    <div style={{ fontSize: '13px', color: config?.errorColor || '#DC2626', marginTop: '4px', animation: 'shake 300ms' }}>
                      {errors.lastName}
                    </div>
                  )}
                </div>
              </div>
              <div>
                <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                  Email Address *
                </label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleChange('email', e.target.value)}
                  onBlur={() => handleBlur('email')}
                  style={{
                    width: '100%',
                    padding: '12px',
                    fontSize: '15px',
                    border: `1px solid ${errors.email && touched.email ? (config?.errorColor || '#DC2626') : (config?.borderColor || '#E9ECEF')}`,
                    borderRadius: '6px',
                    backgroundColor: config?.inputBg || '#F8F9FA',
                    fontFamily: 'inherit'
                  }}
                />
                {errors.email && touched.email && (
                  <div style={{ fontSize: '13px', color: config?.errorColor || '#DC2626', marginTop: '4px', animation: 'shake 300ms' }}>
                    {errors.email}
                  </div>
                )}
              </div>
              <div>
                <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                  Phone Number
                </label>
                <input
                  type="tel"
                  value={formData.phone}
                  onChange={(e) => handleChange('phone', e.target.value)}
                  onBlur={() => handleBlur('phone')}
