                  style={{
                    width: '100%',
                    padding: '12px',
                    fontSize: '15px',
                    border: `1px solid ${errors.phone && touched.phone ? (config?.errorColor || '#DC2626') : (config?.borderColor || '#E9ECEF')}`,
                    borderRadius: '6px',
                    backgroundColor: config?.inputBg || '#F8F9FA',
                    fontFamily: 'inherit'
                  }}
                />
              </div>
            </div>
          </div>
        );

      case 2:
        return (
          <div key="step2" className={slideClass}>
            <h2 style={{ fontSize: '24px', fontWeight: '500', marginBottom: '24px', color: config?.textColor || '#212529' }}>
              {config?.step2Title || 'Business Details'}
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <div>
                <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                  Company Name *
                </label>
                <input
                  type="text"
                  value={formData.company}
                  onChange={(e) => handleChange('company', e.target.value)}
                  onBlur={() => handleBlur('company')}
                  style={{
                    width: '100%',
                    padding: '12px',
                    fontSize: '15px',
                    border: `1px solid ${errors.company && touched.company ? (config?.errorColor || '#DC2626') : (config?.borderColor || '#E9ECEF')}`,
                    borderRadius: '6px',
                    backgroundColor: config?.inputBg || '#F8F9FA',
                    fontFamily: 'inherit'
                  }}
                />
              </div>
              <div>
                <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                  Industry *
                </label>
                <select
                  value={formData.industry}
                  onChange={(e) => handleChange('industry', e.target.value)}
                  style={{
                    width: '100%',
                    padding: '12px',
                    fontSize: '15px',
                    border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
                    borderRadius: '6px',
                    backgroundColor: config?.inputBg || '#F8F9FA',
                    fontFamily: 'inherit'
                  }}
                >
                  <option value="">Select an industry</option>
                  <option value="tech">Technology</option>
                  <option value="finance">Finance</option>
                  <option value="healthcare">Healthcare</option>
                  <option value="retail">Retail</option>
                  <option value="other">Other</option>
                </select>
              </div>
              {formData.industry === 'tech' && (
                <div style={{ animation: 'slideDown 300ms ease-out' }}>
                  <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                    Business Type
                  </label>
                  <select
                    value={formData.businessType}
                    onChange={(e) => handleChange('businessType', e.target.value)}
                    style={{
                      width: '100%',
                      padding: '12px',
                      fontSize: '15px',
                      border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
                      borderRadius: '6px',
                      backgroundColor: config?.inputBg || '#F8F9FA',
                      fontFamily: 'inherit'
                    }}
                  >
                    <option value="">Select type</option>
                    <option value="saas">SaaS</option>
                    <option value="enterprise">Enterprise Software</option>
                    <option value="startup">Startup</option>
                  </select>
                </div>
              )}
              <div>
                <label style={{ display: 'block', fontSize: '14px', fontWeight: '500', marginBottom: '6px', color: config?.textColor || '#212529' }}>
                  Number of Employees
                </label>
                <select
                  value={formData.employees}
                  onChange={(e) => handleChange('employees', e.target.value)}
                  style={{
                    width: '100%',
                    padding: '12px',
                    fontSize: '15px',
                    border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
                    borderRadius: '6px',
                    backgroundColor: config?.inputBg || '#F8F9FA',
                    fontFamily: 'inherit'
                  }}
                >
                  <option value="">Select range</option>
                  <option value="1-10">1-10</option>
                  <option value="11-50">11-50</option>
                  <option value="51-200">51-200</option>
                  <option value="201+">201+</option>
                </select>
              </div>
            </div>
          </div>
        );

      case 3:
        return (
          <div key="step3" className={slideClass}>
            <h2 style={{ fontSize: '24px', fontWeight: '500', marginBottom: '24px', color: config?.textColor || '#212529' }}>
              {config?.step3Title || 'Preferences'}
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer', padding: '16px', backgroundColor: config?.inputBg || '#F8F9FA', borderRadius: '6px', border: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
                <input
                  type="checkbox"
                  checked={formData.newsletter}
                  onChange={(e) => handleChange('newsletter', e.target.checked)}
                  style={{ width: '18px', height: '18px', cursor: 'pointer' }}
                />
                <div>
                  <div style={{ fontSize: '15px', fontWeight: '500', color: config?.textColor || '#212529' }}>
                    Subscribe to newsletter
                  </div>
                  <div style={{ fontSize: '13px', color: '#6C757D', marginTop: '2px' }}>
                    Get weekly updates about new features and tips
                  </div>
                </div>
              </label>
              <label style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer', padding: '16px', backgroundColor: config?.inputBg || '#F8F9FA', borderRadius: '6px', border: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
                <input
                  type="checkbox"
                  checked={formData.notifications}
                  onChange={(e) => handleChange('notifications', e.target.checked)}
                  style={{ width: '18px', height: '18px', cursor: 'pointer' }}
                />
                <div>
                  <div style={{ fontSize: '15px', fontWeight: '500', color: config?.textColor || '#212529' }}>
                    Enable notifications
                  </div>
                  <div style={{ fontSize: '13px', color: '#6C757D', marginTop: '2px' }}>
                    Receive alerts about important updates
                  </div>
                </div>
              </label>
            </div>
          </div>
        );

      case 4:
        return (
          <div key="step4" className={slideClass}>
            <h2 style={{ fontSize: '24px', fontWeight: '500', marginBottom: '24px', color: config?.textColor || '#212529' }}>
              {config?.step4Title || 'Review & Submit'}
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', padding: '20px', backgroundColor: config?.inputBg || '#F8F9FA', borderRadius: '6px', border: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
              <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px', paddingBottom: '12px', borderBottom: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
                <div style={{ fontSize: '14px', fontWeight: '500', color: '#6C757D' }}>Name:</div>
                <div style={{ fontSize: '14px', color: config?.textColor || '#212529' }}>{formData.firstName} {formData.lastName}</div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px', paddingBottom: '12px', borderBottom: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
                <div style={{ fontSize: '14px', fontWeight: '500', color: '#6C757D' }}>Email:</div>
                <div style={{ fontSize: '14px', color: config?.textColor || '#212529' }}>{formData.email}</div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px', paddingBottom: '12px', borderBottom: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
                <div style={{ fontSize: '14px', fontWeight: '500', color: '#6C757D' }}>Company:</div>
                <div style={{ fontSize: '14px', color: config?.textColor || '#212529' }}>{formData.company}</div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px', paddingBottom: '12px', borderBottom: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
                <div style={{ fontSize: '14px', fontWeight: '500', color: '#6C757D' }}>Industry:</div>
                <div style={{ fontSize: '14px', color: config?.textColor || '#212529', textTransform: 'capitalize' }}>{formData.industry}</div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px' }}>
                <div style={{ fontSize: '14px', fontWeight: '500', color: '#6C757D' }}>Newsletter:</div>
                <div style={{ fontSize: '14px', color: config?.textColor || '#212529' }}>{formData.newsletter ? 'Yes' : 'No'}</div>
              </div>
            </div>
          </div>
        );
    }
  };

  const progressPercent = (currentStep / totalSteps) * 100;

  return (
    <div className="form-wizard" style={{
      maxWidth: '700px',
      margin: '0 auto',
      backgroundColor: config?.backgroundColor || '#FFFFFF',
      padding: '40px',
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
      borderRadius: '8px'
    }}>
      {/* Progress Bar */}
      {!isSubmitted && (
        <div style={{ marginBottom: '40px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
            <div style={{ fontSize: '13px', color: '#6C757D' }}>Step {currentStep} of {totalSteps}</div>
            <div style={{ fontSize: '13px', fontWeight: '500', color: config?.primaryColor || '#495057' }}>{Math.round(progressPercent)}%</div>
          </div>
          <div style={{ height: '4px', backgroundColor: config?.borderColor || '#E9ECEF', borderRadius: '2px', overflow: 'hidden' }}>
            <div style={{
              height: '100%',
              width: `${progressPercent}%`,
              backgroundColor: config?.primaryColor || '#495057',
              transition: 'width 400ms ease-out',
              borderRadius: '2px'
            }} />
          </div>
        </div>
      )}

      {/* Step Content */}
      <div style={{ minHeight: '400px', position: 'relative', overflow: 'hidden' }}>
        {renderStepContent()}
      </div>

      {/* Navigation Buttons */}
      {!isSubmitted && (
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '32px', paddingTop: '24px', borderTop: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
          <button
            onClick={prevStep}
            disabled={currentStep === 1}
            style={{
              padding: '12px 24px',
              fontSize: '15px',
              fontWeight: '500',
              border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
              borderRadius: '6px',
              backgroundColor: '#FFFFFF',
              color: config?.textColor || '#212529',
              cursor: currentStep === 1 ? 'not-allowed' : 'pointer',
              opacity: currentStep === 1 ? 0.5 : 1,
              transition: 'all 200ms ease-out',
              fontFamily: 'inherit'
            }}
          >
            Previous
          </button>
          {currentStep < totalSteps ? (
            <button
              onClick={nextStep}
              disabled={!canProceed(currentStep)}
              style={{
                padding: '12px 24px',
                fontSize: '15px',
                fontWeight: '500',
                border: 'none',
                borderRadius: '6px',
                backgroundColor: canProceed(currentStep) ? (config?.primaryColor || '#495057') : '#CED4DA',
                color: '#FFFFFF',
                cursor: canProceed(currentStep) ? 'pointer' : 'not-allowed',
                transition: 'all 200ms ease-out',
                fontFamily: 'inherit'
              }}
            >
              Next Step
            </button>
          ) : (
            <button
              onClick={handleSubmit}
              style={{
                padding: '12px 32px',
                fontSize: '15px',
                fontWeight: '500',
                border: 'none',
                borderRadius: '6px',
                backgroundColor: config?.successColor || '#2D7D3E',
                color: '#FFFFFF',
                cursor: 'pointer',
                transition: 'all 200ms ease-out',
                fontFamily: 'inherit'
              }}
            >
              Submit Form
            </button>
          )}
        </div>
      )}

      <style>{`
        .slide-in-right { animation: slideInRight 400ms ease-out; }
        .slide-in-left { animation: slideInLeft 400ms ease-out; }
        @keyframes slideInRight {
          from { opacity: 0; transform: translateX(50px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes slideInLeft {
          from { opacity: 0; transform: translateX(-50px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        @keyframes slideDown {
          from { opacity: 0; transform: translateY(-10px); max-height: 0; }
          to { opacity: 1; transform: translateY(0); max-height: 100px; }
        }
        @keyframes fadeInScale {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
        @keyframes successPop {
          0% { transform: scale(0); }
          50% { transform: scale(1.1); }
          100% { transform: scale(1); }
        }
      `}</style>
    </div>
  );
}

forms-saasonboarding:
const MANIFEST = {
  "type": "Forms.SaaSOnboarding",
  "description": "Multi-step onboarding wizard with progress tracking, validation states, and review summary.",
  "editorElement": {
    "selector": ".onboarding-wizard",
    "displayName": "SaaS Onboarding",
    "archetype": "container",
    "data": {
      "title": {
        "dataType": "text",
        "displayName": "Form Title",
        "defaultValue": "Set up your workspace",
        "group": "Content"
      },
      "step1Title": {
        "dataType": "text",
        "displayName": "Step 1 Title",
        "defaultValue": "Account Details",
        "group": "Content"
      },
      "step2Title": {
        "dataType": "text",
        "displayName": "Step 2 Title",
        "defaultValue": "Workspace Info",
        "group": "Content"
      },
      "step3Title": {
        "dataType": "text",
        "displayName": "Step 3 Title",
        "defaultValue": "Personalize",
        "group": "Content"
      },
      "step4Title": {
        "dataType": "text",
        "displayName": "Step 4 Title",
        "defaultValue": "Review",
        "group": "Content"
      },
      "primaryColor": {
        "dataType": "color",
        "displayName": "Primary Color",
        "defaultValue": "#2563EB",
        "group": "Colors"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "borderRadius": {
        "dataType": "number",
        "displayName": "Radius (px)",
        "defaultValue": 12,
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontal",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  // Config
  const title = config?.title || "Set up your workspace";
  const primaryColor = config?.primaryColor || "#2563EB";
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const borderRadius = parseInt(config?.borderRadius || "12");

  const steps = [
    config?.step1Title || "Account Details",
    config?.step2Title || "Workspace Info",
    config?.step3Title || "Personalize",
    config?.step4Title || "Review"
  ];

  // State
  const [currentStep, setCurrentStep] = React.useState(0);
  const [direction, setDirection] = React.useState(1); // 1 = forward, -1 = back
  const [isAnimating, setIsAnimating] = React.useState(false);

  // Form Data State
  const [formData, setFormData] = React.useState({
    fullName: '',
    email: '',
    workspaceName: '',
    teamSize: '1-10',
    role: 'Developer',
    goals: ['Project Management']
  });

  // Derived Values
  const progress = ((currentStep + 1) / steps.length) * 100;

  // Handlers
  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setDirection(1);
      setIsAnimating(true);
      setTimeout(() => {
        setCurrentStep(prev => prev + 1);
        setIsAnimating(false);
      }, 300);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setDirection(-1);
      setIsAnimating(true);
      setTimeout(() => {
        setCurrentStep(prev => prev - 1);
        setIsAnimating(false);
      }, 300);
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const toggleGoal = (goal) => {
    setFormData(prev => {
      const goals = prev.goals.includes(goal)
        ? prev.goals.filter(g => g !== goal)
        : [...prev.goals, goal];
      return { ...prev, goals };
    });
  };

  // Styles
  const labelStyle = {
    display: 'block',
    fontSize: '13px',
    fontWeight: '500',
    color: '#374151',
    marginBottom: '6px',
    marginTop: '16px'
  };

  const inputStyle = {
    width: '100%',
    padding: '10px 12px',
    fontSize: '14px',
    border: '1px solid #E5E7EB',
    borderRadius: '6px',
    outline: 'none',
    transition: 'border-color 0.2s, box-shadow 0.2s',
    color: '#1F2937'
  };

  // Render Steps
  const renderStepContent = () => {
    switch (currentStep) {
      case 0: // Account
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>Welcome! First things first.</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>Create your profile to get started.</p>
            </div>

            <label style={labelStyle}>Full Name</label>
            <input 
              type="text" 
              placeholder="Jane Doe"
              value={formData.fullName}
              onChange={(e) => handleChange('fullName', e.target.value)}
              style={inputStyle}
              onFocus={(e) => e.target.style.borderColor = primaryColor}
              onBlur={(e) => e.target.style.borderColor = '#E5E7EB'}
            />

            <label style={labelStyle}>Email Address</label>
            <input 
              type="email" 
              placeholder="jane@company.com"
              value={formData.email}
              onChange={(e) => handleChange('email', e.target.value)}
              style={inputStyle}
              onFocus={(e) => e.target.style.borderColor = primaryColor}
              onBlur={(e) => e.target.style.borderColor = '#E5E7EB'}
            />
          </div>
        );

      case 1: // Workspace
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>Name your workspace.</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>You can always change this later.</p>
            </div>

            <label style={labelStyle}>Workspace Name</label>
            <input 
              type="text" 
              placeholder="Acme Corp"
              value={formData.workspaceName}
              onChange={(e) => handleChange('workspaceName', e.target.value)}
              style={inputStyle}
              onFocus={(e) => e.target.style.borderColor = primaryColor}
              onBlur={(e) => e.target.style.borderColor = '#E5E7EB'}
            />

            <label style={labelStyle}>Team Size</label>
            <div style={{ position: 'relative' }}>
              <select 
                value={formData.teamSize}
                onChange={(e) => handleChange('teamSize', e.target.value)}
                style={{ ...inputStyle, appearance: 'none', background: 'white' }}
                onFocus={(e) => e.target.style.borderColor = primaryColor}
                onBlur={(e) => e.target.style.borderColor = '#E5E7EB'}
              >
                <option value="1-10">1-10 Employees</option>
                <option value="11-50">11-50 Employees</option>
                <option value="50-200">50-200 Employees</option>
                <option value="200+">200+ Employees</option>
              </select>
              <div style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#6B7280', fontSize: '10px' }}>▼</div>
            </div>
          </div>
        );

      case 2: // Personalize
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>How will you use it?</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>Select all that apply.</p>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {['Project Management', 'CRM', 'Software Development', 'Marketing'].map(goal => (
                <button
                  key={goal}
                  onClick={() => toggleGoal(goal)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    padding: '12px',
                    borderRadius: '8px',
                    border: `1px solid ${formData.goals.includes(goal) ? primaryColor : '#E5E7EB'}`,
                    backgroundColor: formData.goals.includes(goal) ? `${primaryColor}10` : 'white',
                    cursor: 'pointer',
                    transition: 'all 0.2s',
                    textAlign: 'left'
                  }}
                >
                  <div style={{
                    width: '18px',
                    height: '18px',
                    borderRadius: '4px',
                    border: `1px solid ${formData.goals.includes(goal) ? primaryColor : '#D1D5DB'}`,
                    backgroundColor: formData.goals.includes(goal) ? primaryColor : 'transparent',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    marginRight: '12px',
                    color: 'white',
                    fontSize: '12px'
                  }}>
                    {formData.goals.includes(goal) && '✓'}
                  </div>
                  <span style={{ fontSize: '14px', color: '#374151', fontWeight: '500' }}>{goal}</span>
                </button>
              ))}
            </div>
          </div>
        );

      case 3: // Review
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>Review & Launch</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>Please verify your details.</p>
            </div>

            <div style={{ backgroundColor: '#F9FAFB', borderRadius: '8px', padding: '16px', border: '1px solid #F3F4F6' }}>
              {[
                { label: 'Name', value: formData.fullName || 'Not provided' },
                { label: 'Email', value: formData.email || 'Not provided' },
                { label: 'Workspace', value: formData.workspaceName || 'Not provided' },
                { label: 'Team Size', value: formData.teamSize },
                { label: 'Goals', value: formData.goals.join(', ') || 'None selected' }
              ].map((item, i) => (
                <div key={i} style={{ marginBottom: i === 4 ? 0 : '12px', paddingBottom: i === 4 ? 0 : '12px', borderBottom: i === 4 ? 'none' : '1px solid #E5E7EB' }}>
                  <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '0.05em', color: '#9CA3AF', marginBottom: '2px' }}>{item.label}</div>
                  <div style={{ fontSize: '14px', color: '#1F2937', fontWeight: '500' }}>{item.value}</div>
                </div>
              ))}
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div className="onboarding-wizard" style={{
      width: '100%',
      minHeight: '600px',
      backgroundColor: '#F3F4F6',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <div style={{
        width: '100%',
        maxWidth: '480px',
        backgroundColor: backgroundColor,
        borderRadius: `${borderRadius}px`,
        boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        overflow: 'hidden'
      }}>
        {/* Progress Header */}
        <div style={{ padding: '32px 32px 0 32px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px' }}>
            <span style={{ fontSize: '12px', fontWeight: '600', color: primaryColor, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Step {currentStep + 1} of {steps.length}
            </span>
            <span style={{ fontSize: '12px', fontWeight: '600', color: '#9CA3AF' }}>
              {steps[currentStep]}
            </span>
          </div>

          <div style={{ width: '100%', height: '6px', backgroundColor: '#F3F4F6', borderRadius: '3px', overflow: 'hidden' }}>
            <div style={{
              width: `${progress}%`,
              height: '100%',
              backgroundColor: primaryColor,
              borderRadius: '3px',
              transition: 'width 0.4s cubic-bezier(0.4, 0, 0.2, 1)'
            }} />
          </div>
        </div>

        {/* Content Area */}
        <div style={{ 
          padding: '32px',
          minHeight: '380px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between'
        }}>
          {/* Animated Content Wrapper */}
          <div style={{
            opacity: isAnimating ? 0 : 1,
            transform: isAnimating ? `translateX(${direction * -10}px)` : 'translateX(0)',
            transition: 'all 0.3s ease',
            flex: 1
          }}>
            {!isAnimating && renderStepContent()}
          </div>

          {/* Navigation Buttons */}
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '32px', paddingTop: '24px', borderTop: '1px solid #F3F4F6' }}>
            <button
              onClick={handleBack}
              disabled={currentStep === 0}
              style={{
                background: 'none',
                border: 'none',
                color: currentStep === 0 ? '#D1D5DB' : '#6B7280',
                fontWeight: '500',
                fontSize: '14px',
                cursor: currentStep === 0 ? 'not-allowed' : 'pointer',
                padding: '8px 16px',
                borderRadius: '6px',
                transition: 'color 0.2s'
              }}
              onMouseEnter={(e) => { if(currentStep !== 0) e.target.style.color = '#111827' }}
              onMouseLeave={(e) => { if(currentStep !== 0) e.target.style.color = '#6B7280' }}
            >
              Back
            </button>

            <button
              onClick={handleNext}
              style={{
                backgroundColor: primaryColor,
                border: 'none',
                color: '#FFFFFF',
                fontWeight: '500',
                fontSize: '14px',
                padding: '10px 24px',
                borderRadius: '6px',
                cursor: 'pointer',
                boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
                transition: 'background-color 0.2s',
                display: 'flex',
                alignItems: 'center'
              }}
              onMouseEnter={(e) => e.target.style.opacity = '0.9'}
              onMouseLeave={(e) => e.target.style.opacity = '1'}
            >
              {currentStep === steps.length - 1 ? 'Launch Workspace' : 'Continue'} 
              {currentStep !== steps.length - 1 && <span style={{ marginLeft: '6px' }}>→</span>}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

