const MANIFEST = {
  "type": "Form.Conversational",
  "description": "Mad-libs style conversational contact form",
  "editorElement": {
    "selector": ".conversational-form",
    "displayName": "Conversational Form",
    "archetype": "container",
    "data": {
      "introText": { "dataType": "text", "defaultValue": "Hello, my name is", "group": "Content" },
      "backgroundColor": { "dataType": "color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "primaryColor": { "dataType": "color", "defaultValue": "#111111", "group": "Colors" }
    }
  }
};

function Component({ config = {} }) {
  const intro = config?.introText || "Hello, my name is";
  const bg = config?.backgroundColor || "#FFFFFF";
  const primary = config?.primaryColor || "#111111";

  const inputStyle = {
    border: 'none',
    borderBottom: `2px solid ${primary}30`,
    fontSize: 'clamp(24px, 4vw, 48px)',
    fontFamily: 'inherit',
    color: primary,
    background: 'transparent',
    padding: '0 10px 10px 0',
    margin: '0 10px',
    outline: 'none',
    width: 'auto',
    minWidth: '200px',
    maxWidth: '100%',
    transition: 'border-color 0.3s ease'
  };

  const focusStyle = (e) => e.target.style.borderBottomColor = primary;
  const blurStyle = (e) => e.target.style.borderBottomColor = `${primary}30`;

  return (
    <div style={{
      backgroundColor: bg,
      minHeight: '80vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px',
      fontFamily: 'Inter, sans-serif'
    }}>
      <form style={{ maxWidth: '900px', lineHeight: '1.6' }}>
        <div style={{ 
          fontSize: 'clamp(24px, 4vw, 48px)', 
          color: primary,
          fontWeight: '300' 
        }}>
          {intro}
          <input 
            type="text" 
            placeholder="your name" 
            style={inputStyle}
            onFocus={focusStyle}
            onBlur={blurStyle}
          />
          and I'm from
          <input 
            type="text" 
            placeholder="company/location" 
            style={inputStyle}
            onFocus={focusStyle}
            onBlur={blurStyle}
          />
          .<br/><br/>
          I'm looking for help with
          <select style={{...inputStyle, cursor: 'pointer', appearance: 'none', borderRadius: 0}}>
            <option>Web Design</option>
            <option>Branding</option>
            <option>Development</option>
          </select>
          .<br/><br/>
          You can reach me at
          <input 
            type="email" 
            placeholder="your@email.com" 
            style={inputStyle}
            onFocus={focusStyle}
            onBlur={blurStyle}
          />
          .
        </div>

        <button style={{
          marginTop: '60px',
          backgroundColor: primary,
          color: bg,
          border: 'none',
          padding: '20px 60px',
          fontSize: '18px',
          textTransform: 'uppercase',
          letterSpacing: '0.1em',
          cursor: 'pointer',
          borderRadius: '4px',
          transition: 'transform 0.2s ease'
        }}
        onMouseEnter={e => e.target.style.transform = 'scale(1.05)'}
        onMouseLeave={e => e.target.style.transform = 'scale(1)'}
        >
          Send Request
        </button>
      </form>
    </div>
  );
}

