          textTransform: 'uppercase',
          color: textSecondary,
          marginBottom: '60px'
        }}>Our Values</p>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '60px 80px'
        }}>
          {values.map((value, i) => (
            <div key={i} style={{ borderLeft: `1px solid ${dividerColor}`, paddingLeft: '30px' }}>
              <h3 style={{
                fontFamily: headingFont,
                fontSize: '28px',
                fontWeight: 400,
                marginBottom: '12px',
                fontStyle: 'italic'
              }}>{value.title}</h3>
              <p style={{
                fontSize: '15px',
                color: textSecondary,
                lineHeight: 1.6
              }}>{value.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Leadership Section */}
      <section
        ref={el => sectionRefs.current.team = el}
        data-section="team"
        className={`editorial-section ${isVisible('team') ? 'visible' : ''}`}
        style={{
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <p style={{
          fontSize: '12px',
          letterSpacing: '0.2em',
          textTransform: 'uppercase',
          color: textSecondary,
          marginBottom: '60px'
        }}>Leadership</p>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(4, 1fr)',
          gap: '40px'
        }}>
          {team.map((member, i) => (
            <div key={i} className="team-member" style={{ cursor: 'pointer' }}>
              <div style={{
                aspectRatio: '3/4',
                backgroundColor: dividerColor,
                marginBottom: '20px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}>
                <span style={{
                  fontFamily: headingFont,
                  fontSize: '32px',
                  color: textSecondary,
                  fontStyle: 'italic'
                }}>{member.initials}</span>
              </div>
              <h4 style={{
                fontFamily: headingFont,
                fontSize: '18px',
                fontWeight: 400,
                marginBottom: '4px'
              }}>{member.name}</h4>
              <p style={{
                fontSize: '13px',
                color: textSecondary
              }}>{member.role}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Clients Section */}
      <section
        ref={el => sectionRefs.current.clients = el}
        data-section="clients"
        className={`editorial-section ${isVisible('clients') ? 'visible' : ''}`}
        style={{
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <div className="editorial-divider" style={{ marginBottom: '60px' }} />
        <p style={{
          fontSize: '12px',
          letterSpacing: '0.2em',
          textTransform: 'uppercase',
          color: textSecondary,
          marginBottom: '40px',
          textAlign: 'center'
        }}>Select Clients</p>

        <div style={{
          display: 'flex',
          justifyContent: 'center',
          flexWrap: 'wrap',
          gap: '20px 60px'
        }}>
          {clients.map((client, i) => (
            <span key={i} style={{
              fontFamily: headingFont,
              fontSize: '18px',
              color: textSecondary,
              fontStyle: 'italic'
            }}>{client}</span>
          ))}
        </div>
      </section>

      {/* CTA Section */}
      <section
        ref={el => sectionRefs.current.cta = el}
        data-section="cta"
        className={`editorial-section ${isVisible('cta') ? 'visible' : ''}`}
        style={{
          padding: '160px 80px',
          textAlign: 'center'
        }}
      >
        <h2 style={{
          fontFamily: headingFont,
          fontSize: 'clamp(32px, 4vw, 48px)',
          fontWeight: 400,
          fontStyle: 'italic',
          marginBottom: '50px',
          maxWidth: '600px',
          margin: '0 auto 50px'
        }}>Let's create something timeless together</h2>

        <button className="cta-button" style={{
          fontFamily: bodyFont,
          fontSize: '13px',
          letterSpacing: '0.15em',
          textTransform: 'uppercase',
          padding: '18px 48px',
          background: 'transparent',
          color: textPrimary,
          cursor: 'pointer'
        }}>{ctaText}</button>
      </section>

      <footer style={{
        padding: '40px 80px',
        borderTop: `1px solid ${dividerColor}`,
        textAlign: 'center'
      }}>
        <p style={{
          fontSize: '12px',
          color: textSecondary,
          letterSpacing: '0.1em'
        }}>© {new Date().getFullYear()} {companyName}. All rights reserved.</p>
      </footer>
    </div>
  );
}
